export function generateCacheKey(query: string, fingerprintOrIds: string | string[]): string {
  const fingerprint = typeof fingerprintOrIds === 'string'
    ? fingerprintOrIds
    : [...fingerprintOrIds].sort().join(',');
  return simpleHash(`${query}|${fingerprint}`);
